 let shape="";
 if(p.cat==="chargers")shape='<g filter="url(#sh)" transform="rotate(-8 120 88)"><rect x="82" y="25" width="76" height="112" rx="19" fill="url(#body)"/><rect x="92" y="37" width="56" height="78" rx="12" fill="'+d+'"/><path d="M124 48 106 81h16l-6 23 26-39h-17z" fill="'+a+'"/><rect x="98" y="135" width="12" height="17" rx="3" fill="#c7d6e8"/><rect x="132" y="135" width="12" height="17" rx="3" fill="#c7d6e8"/></g>';
 else if(p.cat==="power")shape='<g filter="url(#sh)" transform="rotate(-8 120 88)"><rect x="59" y="40" width="122" height="92" rx="19" fill="url(#body)"/><rect x="72" y="53" width="96" height="65" rx="12" fill="'+d+'"/><rect x="87" y="68" width="66" height="8" rx="4" fill="'+a+'"/><rect x="89" y="88" width="62" height="5" rx="2.5" fill="#dbeafe"/><circle cx="120" cy="107" r="4" fill="'+a+'"/></g>';
 else if(p.cat==="cables")shape='<g filter="url(#sh)"><path d="M52 70 C38 145 110 150 114 98 C118 43 194 42 190 96 C188 127 156 129 144 109" fill="none" stroke="'+d+'" stroke-width="13" stroke-linecap="round"/><path d="M52 70 C38 145 110 150 114 98 C118 43 194 42 190 96 C188 127 156 129 144 109" fill="none" stroke="'+a+'" stroke-width="4" stroke-linecap="round"/><rect x="39" y="54" width="25" height="27" rx="7" fill="#d9e5f2" stroke="'+d+'" stroke-width="3"/><rect x="132" y="100" width="26" height="30" rx="7" fill="#d9e5f2" stroke="'+d+'" stroke-width="3"/></g>';
 else if(p.cat==="audio")shape='<g filter="url(#sh)"><rect x="53" y="34" width="134" height="92" rx="28" fill="url(#body)"/><path d="M67 61 Q120 27 173 61" fill="none" stroke="#fff" stroke-width="3"/><g fill="'+d+'"><rect x="78" y="60" width="26" height="49" rx="13"/><rect x="136" y="60" width="26" height="49" rx="13"/></g><g fill="'+a+'"><circle cx="91" cy="74" r="5"/><circle cx="149" cy="74" r="5"/></g></g>';
 else if(p.cat==="wireless")shape='<g filter="url(#sh)"><rect x="50" y="61" width="140" height="68" rx="30" fill="url(#body)"/><circle cx="120" cy="94" r="28" fill="none" stroke="'+a+'" stroke-width="7"/><circle cx="120" cy="94" r="15" fill="none" stroke="#fff" stroke-width="4"/></g>';
 else if(p.cat==="protection")shape='<g filter="url(#sh)" transform="rotate(7 120 88)"><rect x="78" y="17" width="84" height="139" rx="20" fill="url(#body)"/><rect x="86" y="25" width="68" height="123" rx="15" fill="'+s+'" stroke="'+d+'" stroke-width="3"/><rect x="93" y="33" width="33" height="34" rx="9" fill="'+d+'"/><circle cx="103" cy="44" r="6" fill="'+a+'"/><circle cx="118" cy="56" r="6" fill="'+a+'"/></g>';
 else shape='<g filter="url(#sh)"><rect x="81" y="23" width="78" height="108" rx="17" fill="url(#body)"/><rect x="90" y="32" width="60" height="89" rx="10" fill="'+d+'"/><rect x="97" y="40" width="46" height="72" rx="7" fill="'+s+'"/><path d="M65 136h110l-13 12H78z" fill="'+a+'"/></g>';
 const label=esc(p.name.en.split(" ").slice(0,3).join(" ").slice(0,25).toUpperCase());
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 180" role="img" aria-label="'+esc(p.name.fa)+'"><defs><linearGradient id="'+g+'" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="'+s+'"/></linearGradient><linearGradient id="body" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff"/><stop offset=".45" stop-color="'+a+'"/><stop offset="1" stop-color="'+d+'"/></linearGradient><filter id="sh" x="-30%" y="-30%" width="160%" height="180%"><feDropShadow dx="0" dy="7" stdDeviation="6" flood-color="'+d+'" flood-opacity=".22"/></filter></defs><rect x="2" y="2" width="236" height="176" rx="20" fill="url(#'+g+')"/><circle cx="194" cy="35" r="27" fill="#fff" opacity=".55"/><circle cx="35" cy="145" r="34" fill="'+a+'" opacity=".09"/>'+shape+'<text x="120" y="168" text-anchor="middle" font-family="Arial,sans-serif" font-size="9" font-weight="700" letter-spacing=".6" fill="'+d+'">'+label+'</text></svg>';
