function renderFilters(){
 $("filters").setAttribute("aria-label",lang==="en"?"Filter products":"فیلتر محصولات");
 $("filters").innerHTML=[{id:"all",en:"All categories",fa:"همهٔ دسته‌ها"},...cats].map(c=>'<button type="button" class="filter '+(activeCat===c.id?'active':'')+'" data-cat="'+c.id+'" aria-pressed="'+String(activeCat===c.id)+'">'+c[lang]+'</button>').join("");
 $("filters").querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{activeCat=b.dataset.cat;currentPage=1;renderFilters();renderProducts()}));
}
function orderHref(){return "https://ig.me/m/"+encodeURIComponent(INSTAGRAM_USERNAME)}
let currentPage=1;
function renderProducts(){
 const filtered=products.filter(p=>(activeCat==="all"||p.cat===activeCat)&&((p.name[lang]+" "+p.desc[lang]).toLowerCase().includes(query.toLowerCase())));
 const pages=Math.max(1,Math.ceil(filtered.length/10));currentPage=Math.min(currentPage,pages);
 const pageItems=filtered.slice((currentPage-1)*10,currentPage*10);
 const groups=(activeCat==="all"?cats:cats.filter(c=>c.id===activeCat)).map(c=>{
  const items=pageItems.filter(p=>p.cat===c.id);if(!items.length)return "";
  return '<section class="category-section" data-category="'+c.id+'"><div class="category-heading"><div><h3>'+c[lang]+'</h3><p>'+c[lang==="en"?"descEn":"descFa"]+'</p></div><span class="category-count">'+items.length+' '+(lang==="fa"?"محصول":"items")+'</span></div><div class="grid category-grid">'+items.map(p=>'<article class="product" data-category="'+p.cat+'"><a class="product-detail-link" href="/product/'+encodeURIComponent(p.id)+'"><div class="visual"><div class="poster-art">'+posterSVG(p)+'</div><span class="tag">'+esc(lang==="en"?p.tag:p.tagFa)+'</span></div><h3>'+esc(p.name[lang])+'</h3></a><div class="price">'+(lang==="fa"?"استعلام قیمت":"Price inquiry")+'</div><a class="buy instagram-order" href="'+orderHref()+'" target="_blank" rel="noopener noreferrer"><span>'+(lang==="fa"?"سفارش در دایرکت":"Order in Direct")+'</span><span aria-hidden="true">↗</span></a></article>').join("")+'</div></section>';
 }).join("");
 $("grid").innerHTML=groups||'<p class="empty">'+(lang==="fa"?"محصولی پیدا نشد؛ عبارت دیگری را جست‌وجو کنید.":"No matching products. Try another search.")+'</p>';
 const pager=$("pagination");if(pager)pager.innerHTML=pages>1?'<button type="button" class="page-btn" data-page="'+Math.max(1,currentPage-1)+'" '+(currentPage===1?'disabled':'')+'>'+(lang==="fa"?"قبلی":"Previous")+'</button><span class="page-status">'+(lang==="fa"?"صفحهٔ ":"Page ")+currentPage+(lang==="fa"?" از ":" of ")+pages+'</span><button type="button" class="page-btn" data-page="'+Math.min(pages,currentPage+1)+'" '+(currentPage===pages?'disabled':'')+'>'+(lang==="fa"?"بعدی":"Next")+'</button>':'<span class="page-status">'+filtered.length+' '+(lang==="fa"?"محصول":"products")+'</span>';
 pager?.querySelectorAll("[data-page]").forEach(b=>b.addEventListener("click",()=>{currentPage=Number(b.dataset.page);renderProducts();$("products").scrollIntoView({behavior:"smooth",block:"start"})}));
}
function setLang(next){
 lang=next;document.documentElement.lang=lang;document.documentElement.dir=lang==="fa"?"rtl":"ltr";
 $("enBtn").classList.toggle("active",lang==="en");$("faBtn").classList.toggle("active",lang==="fa");
 $("enBtn").setAttribute("aria-pressed",String(lang==="en"));$("faBtn").setAttribute("aria-pressed",String(lang==="fa"));
 document.querySelectorAll("[data-en][data-fa]").forEach(el=>el.innerHTML=el.dataset[lang]);
 $("search").placeholder=$("search").dataset["placeholder"+(lang==="en"?"En":"Fa")];
 $("search").setAttribute("aria-label",lang==="en"?"Search products":"جست‌وجوی محصولات");
 renderFilters();renderProducts();
}
$("enBtn").addEventListener("click",()=>location.assign("/en/"));$("faBtn").addEventListener("click",()=>location.assign("/"));
$("search").addEventListener("input",e=>{query=e.target.value;currentPage=1;renderProducts()});
$("search").addEventListener("search",e=>{query=e.target.value;renderProducts()});
$("year").textContent=new Date().getFullYear();setLang(lang);
